1	import { useState } from 'react'
2	import { toast } from 'sonner'
3	import { Gavel, TrendingUp } from 'lucide-react'
4	import { generateId } from '@/crypto'
5	import { placeBid, setProxyBid } from '@/services/biddingEngine'
6	import { getMinimumIncrement } from '@/utils/increment'
7	import { useAuthStore } from '@/store/authStore'
8	import { Button, Input } from '@/components/ui'
9	import type { Auction } from '@/types'
10	
11	interface Props {
12	  auction: Auction
13	  /** Amount the current user already has reserved for this auction (0 if first bid) */
14	  userDepositHeld: number
15	  onBidPlaced: () => void
16	}
17	
18	export function BidForm({ auction, userDepositHeld, onBidPlaced }: Props) {
19	  const currentUser = useAuthStore((s) => s.currentUser)
20	  const [tab, setTab] = useState<'manual' | 'proxy'>('manual')
21	  const [amount, setAmount] = useState('')
22	  const [proxyMax, setProxyMax] = useState('')
23	  const [isSubmitting, setIsSubmitting] = useState(false)
24	
25	  if (!currentUser) return null
26	
27	  const resolvedIncrement = getMinimumIncrement(
28	    auction.currentPrice,
29	    auction.incrementTiers,
30	    auction.minimumIncrement,
31	  )
32	  const minBid = auction.currentPrice + resolvedIncrement
33	  const isOpen = auction.status === 'Active' || auction.status === 'Extended'
34	
35	  const handleManualBid = async () => {
36	    const parsed = Number(amount)
37	    if (isNaN(parsed) || parsed < minBid) {
38	      toast.error(`Minimum bid is ${String(minBid)}`)
39	      return
40	    }
41	
42	    setIsSubmitting(true)
43	    try {
44	      const result = await placeBid(
45	        auction.id,
46	        currentUser.id,
47	        currentUser.displayName,
48	        parsed,
49	        generateId(),
50	        auction.depositAmount,
51	        userDepositHeld,
52	      )
53	      if (result.success) {
54	        toast.success(result.message)
55	        if (result.extended) toast.info('⏱ Auction extended by 2 minutes (anti-sniping)')
56	        setAmount('')
57	        onBidPlaced()
58	      } else {
59	        toast.error(result.message)
60	      }
61	    } catch {
62	      toast.error('Failed to place bid. Please try again.')
63	    } finally {
64	      setIsSubmitting(false)
65	    }
66	  }
67	
68	  const handleProxyBid = async () => {
69	    const parsed = Number(proxyMax)
70	    if (isNaN(parsed) || parsed <= auction.currentPrice) {
71	      toast.error(`Proxy max must exceed current price (${String(auction.currentPrice)})`)
72	      return
73	    }
74	
75	    setIsSubmitting(true)
76	    try {
77	      const result = await setProxyBid(
78	        auction.id,
79	        currentUser.id,
80	        currentUser.displayName,
81	        parsed,
82	        auction.depositAmount,
83	        userDepositHeld,
84	      )
85	      if (result.success) {
86	        toast.success(result.message)
87	        setProxyMax('')
88	        onBidPlaced()
89	      } else {
90	        toast.error(result.message)
91	      }
92	    } catch {
93	      toast.error('Failed to set proxy bid. Please try again.')
94	    } finally {
95	      setIsSubmitting(false)
96	    }
97	  }
98	
99	  if (!isOpen) {
100	    return (
101	      <div className="rounded-xl bg-surface-800/50 border border-surface-700 px-4 py-3 text-center text-sm text-surface-500">
102	        This auction is not currently accepting bids.
103	      </div>
104	    )
105	  }
106	
107	  return (
108	    <div className="space-y-4">
109	      {/* Tab toggle */}
110	      <div className="flex rounded-lg bg-surface-800 p-1 gap-1">
111	        {(['manual', 'proxy'] as const).map((t) => (
112	          <button
113	            key={t}
114	            onClick={() => {
115	              setTab(t)
116	            }}
117	            className={[
118	              'flex-1 py-1.5 rounded-md text-xs font-medium transition-colors',
119	              tab === t
120	                ? 'bg-surface-700 text-surface-100'
121	                : 'text-surface-500 hover:text-surface-300',
122	            ].join(' ')}
123	          >
124	            {t === 'manual' ? 'Manual Bid' : 'Proxy Bid'}
125	          </button>
126	        ))}
127	      </div>
128	
129	      {tab === 'manual' ? (
130	        <div className="space-y-3">
131	          <Input
132	            label="Your bid"
133	            type="number"
134	            min={minBid}
135	            step={resolvedIncrement}
136	            value={amount}
137	            onChange={(e) => {
138	              setAmount(e.target.value)
139	            }}
140	            placeholder={`Min: ${String(minBid)}`}
141	            hint={`Current price: ${String(auction.currentPrice)} · Min increment: ${String(resolvedIncrement)}`}
142	            leftIcon={<Gavel className="w-4 h-4" />}
143	          />
144	          <Button
145	            className="w-full"
146	            isLoading={isSubmitting}
147	            onClick={() => {
148	              void handleManualBid()
149	            }}
150	          >
151	            Place Bid
152	          </Button>
153	        </div>
154	      ) : (
155	        <div className="space-y-3">
156	          <Input
157	            label="Maximum proxy amount"
158	            type="number"
159	            min={minBid}
160	            step={resolvedIncrement}
161	            value={proxyMax}
162	            onChange={(e) => {
163	              setProxyMax(e.target.value)
164	            }}
165	            placeholder={`Above ${String(auction.currentPrice)}`}
166	            hint="The engine will auto-bid on your behalf up to this amount"
167	            leftIcon={<TrendingUp className="w-4 h-4" />}
168	          />
169	          <Button
170	            className="w-full"
171	            variant="secondary"
172	            isLoading={isSubmitting}
173	            onClick={() => {
174	              void handleProxyBid()
175	            }}
176	          >
177	            Set Proxy Bid
178	          </Button>
179	        </div>
180	      )}
181	
182	      <p className="text-xs text-surface-600 text-center">
183	        Deposit hold: {auction.depositAmount} · Deducted only on win
184	      </p>
185	    </div>
186	  )
187	}
188

